class MergeRankedFeedsTests(unittest.TestCase):
    def test_merges_records_in_nonincreasing_score_order(self):
        feeds = [
            [{"item": "a10", "score": 10}, {"item": "a7", "score": 7}],
            [{"item": "b9", "score": 9}, {"item": "b6", "score": 6}],
            [{"item": "c8", "score": 8}, {"item": "c1", "score": 1}],
        ]

        self.assertEqual(
            solution.merge_ranked_feeds(feeds, 20),
            ["a10", "b9", "c8", "a7", "b6", "c1"],
        )

    def test_equal_scores_use_feed_index_before_later_feeds(self):
        feeds = [
            [
                {"item": "feed0-first", "score": 8},
                {"item": "feed0-second", "score": 8},
                {"item": "feed0-low", "score": 2},
            ],
            [
                {"item": "feed1-first", "score": 8},
                {"item": "feed1-second", "score": 8},
            ],
            [{"item": "feed2", "score": 8}],
        ]

        self.assertEqual(
            solution.merge_ranked_feeds(feeds, 6),
            [
                "feed0-first",
                "feed0-second",
                "feed1-first",
                "feed1-second",
                "feed2",
                "feed0-low",
            ],
        )

    def test_preserves_feed_order_when_scores_decrease_and_repeat(self):
        feeds = [
            [
                {"item": "a", "score": 5},
                {"item": "b", "score": 4},
                {"item": "c", "score": 4},
            ],
            [{"item": "d", "score": 3}],
        ]

        self.assertEqual(solution.merge_ranked_feeds(feeds, 10), ["a", "b", "c", "d"])

    def test_limit_boundaries_and_empty_feeds(self):
        feeds = (
            (),
            ({"item": "x", "score": 0},),
            (),
            ({"item": "y", "score": -1},),
        )

        self.assertEqual(solution.merge_ranked_feeds(feeds, 0), [])
        self.assertEqual(solution.merge_ranked_feeds((), 3), [])
        self.assertEqual(solution.merge_ranked_feeds(feeds, 1), ["x"])
        self.assertEqual(solution.merge_ranked_feeds(feeds, 99), ["x", "y"])

    def test_does_not_modify_feeds_or_records(self):
        feeds = [
            [{"item": "a", "score": 3}, {"item": "b", "score": 1}],
            [{"item": "c", "score": 2}],
        ]
        before = copy.deepcopy(feeds)
        record_ids = [[id(record) for record in feed] for feed in feeds]

        solution.merge_ranked_feeds(feeds, 2)

        self.assertEqual(feeds, before)
        self.assertEqual([[id(record) for record in feed] for feed in feeds], record_ids)

    def test_expected_public_function_exists(self):
        self.assertTrue(callable(solution.merge_ranked_feeds))
        public_defined_callables = [
