def mutable_container_ids(value):
    found = set()

    def visit(current):
        if isinstance(current, (dict, list)):
            identity = id(current)
            if identity in found:
                return
            found.add(identity)
            iterable = current.items() if isinstance(current, dict) else current
            if isinstance(current, dict):
                for key, child in iterable:
                    visit(key)
                    visit(child)
            else:
                for child in iterable:
                    visit(child)
        elif isinstance(current, tuple):
            for child in current:
                visit(child)

    visit(value)
    return found


class ArrangeCollectionsTests(unittest.TestCase):
    def test_sorts_entries_and_collections_stably(self):
        collections = [
            {
                "label": "first-top-seven",
                "entries": [
                    {"id": "a-five-1", "priority": 5},
                    {"id": "a-seven", "priority": 7},
                    {"id": "a-five-2", "priority": 5},
                ],
            },
            {
                "label": "second-top-seven",
                "entries": [
                    {"id": "b-seven-1", "priority": 7},
                    {"id": "b-seven-2", "priority": 7},
                ],
            },
            {
                "label": "top-nine",
                "entries": [{"id": "c-nine", "priority": 9}],
            },
            {
                "label": "low",
                "entries": [{"id": "d-minus-one", "priority": -1}],
            },
        ]

        result = solution.arrange_collections(collections)

        self.assertEqual(
            [collection["label"] for collection in result],
            ["top-nine", "first-top-seven", "second-top-seven", "low"],
        )
        by_label = {collection["label"]: collection for collection in result}
        self.assertEqual(
            [entry["id"] for entry in by_label["first-top-seven"]["entries"]],
            ["a-seven", "a-five-1", "a-five-2"],
        )
        self.assertEqual(
            [entry["id"] for entry in by_label["second-top-seven"]["entries"]],
            ["b-seven-1", "b-seven-2"],
        )

    def test_single_collection_and_single_entry(self):
        collections = [{"label": "only", "entries": [{"priority": 0, "value": "x"}]}]

        self.assertEqual(solution.arrange_collections(collections), collections)

    def test_result_is_deep_copy_and_input_remains_unchanged(self):
        collections = [
            {
                "label": "nested",
                "metadata": {"owners": ["one", {"name": "two"}]},
                "entries": [
                    {
                        "priority": 1,
                        "payload": {"values": [1, {"deep": [2, 3]}]},
                    },
                    {"priority": 4, "payload": {"values": [9]}},
                ],
            }
        ]
        before = copy.deepcopy(collections)
        input_ids = mutable_container_ids(collections)

        result = solution.arrange_collections(collections)

        self.assertEqual(collections, before)
        self.assertTrue(input_ids.isdisjoint(mutable_container_ids(result)))

        result[0]["metadata"]["owners"][1]["name"] = "changed"
        result[0]["entries"][0]["payload"]["values"].append(10)
        self.assertEqual(collections, before)

        collections[0]["metadata"]["owners"].append("new input owner")
        self.assertNotIn("new input owner", result[0]["metadata"]["owners"])


if __name__ == "__main__":
    unittest.main()
