def _decode_name(field):
    if not isinstance(field, str) or field == "":
        raise ValueError("name must be nonempty")

    index = 0
    while index < len(field):
        if field[index] == "%":
            if index + 2 >= len(field):
                raise ValueError("incomplete percent escape")
            pair = field[index + 1:index + 3]
            if any(ch not in "0123456789abcdefABCDEF" for ch in pair):
                raise ValueError("invalid percent escape")
            index += 3
        else:
            index += 1

    try:
        decoded = unquote_to_bytes(field).decode("utf-8", errors="strict")
    except UnicodeDecodeError as exc:
        raise ValueError("invalid UTF-8") from exc
    if decoded == "":
        raise ValueError("name must be nonempty")
    return decoded


def parse_scorecard(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")

    lines = text.splitlines()
    if not lines or lines[0] != "SCORECARD/1":
        raise ValueError("invalid header")

    records = []
    seen = {}
    for line in lines[1:]:
        if line == "":
            continue
        fields = line.split("\t")
        if len(fields) != 3:
            raise ValueError("record must have three fields")

        model = _decode_name(fields[0])
        variant = _decode_name(fields[1])
        score_text = fields[2]
        if not score_text or not score_text.isascii() or not score_text.isdigit():
            raise ValueError("invalid score")
        score = int(score_text)
        if score > 100:
            raise ValueError("score out of range")

        key = (model, variant)
        if key in seen:
            if seen[key] != score:
                raise ValueError("conflicting duplicate")
            continue

        seen[key] = score
        records.append({"model": model, "variant": variant, "score": score})

    return {"records": records}
